title: $:/plugins/huwiki/graph-studio/vis-controls.js
type: application/javascript
module-type: vis-property

Keep Flibbles' native Add Node (click the canvas) and Add Edge (drag
node-to-node) actions intact. Only add an unobtrusive appearance hint
and open the Forge styling popover on a normal node click.
\*/
"use strict";
exports.name="forgeGraphControls";
exports.init=function(network){
 var surface=this.element;
 var stage=surface && surface.closest && surface.closest(".forge-graph-stage");
 if(!stage)return;
 // Expose the local Vis graph instance for exact pointer-coordinate smoke tests.
 // This is scoped to the embedded graph element, not a global API.
 Object.defineProperty(surface,"_forgeVisNetwork",{value:network,configurable:true});
 var doc=surface.ownerDocument;
 var hint=stage.querySelector(".forge-graph-shape-hint");
 if(!hint){
  hint=doc.createElement("div");
  hint.className="forge-graph-shape-hint";
  hint.setAttribute("role","note");
  stage.appendChild(hint);
 }
 var da=($tw.wiki.getTiddlerText("$:/language","")||"").indexOf("/da")!==-1;
 hint.textContent=da?"Klik på en node for at ændre form eller billede":
  "Click a node to change its shape or image";
 // Vis-Network binds its toolbar via Hammer tap handlers. Some embeds
 // deliver a native browser click without Hammer emitting a tap. In that
 // case invoke the *original Vis mode* (not a Forge replacement form).
 // The normal Hammer path wins whenever it has already entered that mode.
 function nativeToolFallback(event){
  var target=event.target && (event.target.nodeType===1?
   event.target:event.target.parentElement);
  var button=target && target.closest && target.closest(".vis-button");
